def solve(values):
    n = len(values)
    max_sum = -float('inf')
    max_start = 0
    current_sum = 0

    for i in range(n):
        current_sum += values[i]
        if i >= 2:
            if current_sum > max_sum:
                max_sum = current_sum
                max_start = i - 2
        elif i == 0:
            current_sum = values[i]
        elif i == 1:
            current_sum = values[i] + values[i-1]

    return max_start
```

